//! Generated by `artifacts/epic_4a/E4a.2_gen_catalog/gen_catalog.py`: every package-backed table and view equals the compiled source it replaces.
#![allow(clippy::all)]

use crate::rules_core::rules_tables as rt;
use std::fmt::Debug;

fn same<A: serde::Serialize + ?Sized, B: serde::Serialize + ?Sized>(
    id: &str,
    catalog: &A,
    compiled: &B,
) {
    let catalog = serde_json::to_string(catalog).expect("serialise catalog rows");
    let compiled = serde_json::to_string(compiled).expect("serialise compiled rows");
    assert!(
        catalog == compiled,
        "{id}: package-backed rows differ from the compiled table"
    );
}

fn same_debug<A: Debug + ?Sized, B: Debug + ?Sized>(id: &str, catalog: &A, compiled: &B) {
    assert!(
        format!("{catalog:?}") == format!("{compiled:?}"),
        "{id}: package-backed rows differ from the compiled table"
    );
}

pub(super) const TABLES: usize = 222;
pub(super) const CALLS: usize = 202;

